CREATE TABLE tbl(a,b PRIMARY KEY) WITHOUT ROWID; INSERT INTO tbl VALUES(1,2),(3,4); CREATE TABLE rlog(idx,old_a,old_b,db_sum_a,db_sum_b,new_a,new_b); CREATE TABLE clog(idx,old_a,old_b,db_sum_a,db_sum_b,new_a,new_b); CREATE TRIGGER bu BEFORE UPDATE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER au AFTER UPDATE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER cu AFTER UPDATE ON tbl WHEN old.a=1 BEGIN INSERT INTO clog VALUES((SELECT coalesce(max(idx),0)+1 FROM clog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER bd BEFORE DELETE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; CREATE TRIGGER ad AFTER DELETE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; CREATE TRIGGER bi BEFORE INSERT ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER ai AFTER INSERT ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END;